<?php if(!defined('ABSPATH')){exit;}$article=$state->article();$view=(new AICS_Manual_SEO_Service())->view($article['id'],get_current_user_id());$a=$view['article'];$analysis=is_array($a['seo_analysis']??null)?$a['seo_analysis']:array(); ?>
<form class="aics-wizard-form" data-operation="save_seo"><header class="aics-wizard-step-header"><p class="aics-eyebrow"><?php esc_html_e('Step 5 of 6','ai-content-studio');?></p><h2 tabindex="-1"><?php esc_html_e('SEO Review','ai-content-studio');?></h2><p><?php echo esc_html(sprintf(__('Target: %1$s · AICS SEO Readiness: %2$d/100','ai-content-studio'),$view['profile']['label'],absint($analysis['score']??0)));?></p></header><div class="aics-seo-summary"><div><span><?php esc_html_e('Passed','ai-content-studio');?></span><strong><?php echo esc_html((string)count($analysis['passed_checks']??array()));?></strong></div><div><span><?php esc_html_e('Warnings','ai-content-studio');?></span><strong><?php echo esc_html((string)count($analysis['warnings']??array()));?></strong></div><div><span><?php esc_html_e('Blocking','ai-content-studio');?></span><strong><?php echo esc_html((string)count($analysis['blocking_issues']??array()));?></strong></div></div><div class="aics-wizard-fields"><div class="aics-field"><label class="aics-field-label"><?php esc_html_e('Focus Keyword','ai-content-studio');?></label><input type="text" name="seo_focus_keyword" value="<?php echo esc_attr($a['seo_focus_keyword']);?>" required></div><div class="aics-field"><label class="aics-field-label"><?php esc_html_e('Slug','ai-content-studio');?></label><input type="text" name="seo_slug" value="<?php echo esc_attr($a['seo_slug']);?>" required></div><div class="aics-field aics-field--full"><label class="aics-field-label"><?php esc_html_e('SEO Title','ai-content-studio');?></label><input type="text" name="seo_title" value="<?php echo esc_attr($a['seo_title']);?>" required></div><div class="aics-field aics-field--full"><label class="aics-field-label"><?php esc_html_e('Meta Description','ai-content-studio');?></label><textarea name="seo_meta_description" required><?php echo esc_textarea($a['seo_meta_description']);?></textarea></div><div class="aics-field aics-field--full"><label class="aics-field-label"><?php esc_html_e('Excerpt','ai-content-studio');?></label><textarea name="seo_excerpt" required><?php echo esc_textarea($a['excerpt']);?></textarea></div><div class="aics-field"><label class="aics-field-label"><?php esc_html_e('Categories','ai-content-studio');?></label><input type="text" name="seo_categories" value="<?php echo esc_attr(implode(', ',$a['seo_categories']??array()));?>"></div><div class="aics-field"><label class="aics-field-label"><?php esc_html_e('Tags','ai-content-studio');?></label><input type="text" name="seo_tags" value="<?php echo esc_attr(implode(', ',$a['seo_tags']??array()));?>"></div><div class="aics-field aics-field--full"><label class="aics-field-label"><?php esc_html_e('Image Alt Text','ai-content-studio');?></label><input type="text" name="seo_image_alt_text" value="<?php echo esc_attr($a['featured_image_alt_text']??'');?>"></div></div><div class="aics-seo-analysis"><?php foreach(array('blocking_issues'=>__('Blocking issues','ai-content-studio'),'warnings'=>__('Warnings','ai-content-studio'),'passed_checks'=>__('Passed checks','ai-content-studio')) as $key=>$label):?><details <?php echo 'blocking_issues'===$key&&!empty($analysis[$key])?'open':'';?>><summary><?php echo esc_html($label.' ('.count($analysis[$key]??array()).')');?></summary><ul><?php foreach($analysis[$key]??array() as $item):?><li><?php echo esc_html(is_array($item)?($item['message']??$item['id']??''):$item);?></li><?php endforeach;?></ul></details><?php endforeach;?></div><footer class="aics-wizard-actions"><button class="button" type="button" data-aics-step="image"><?php esc_html_e('Back','ai-content-studio');?></button><button class="button" type="submit"><?php esc_html_e('Save SEO Data','ai-content-studio');?></button><button class="button button-primary" type="submit" data-aics-operation="apply_seo"><?php esc_html_e('Apply SEO and Continue','ai-content-studio');?></button></footer></form>
